insert into tap_results select is(jsonb_array_length(pg_temp.report('receipts')->'rows'),25,'Daily register has a bounded page, not a lifetime-sized list');
insert into tap_results select is((pg_temp.report('receipts')->>'total')::integer,81,'Full-history count includes records beyond the first page');
insert into tap_results select is((pg_temp.report('receipts','{"offset":25}')->>'next')::integer,50,'Remote next page retains the complete count');
insert into tap_results select is(jsonb_array_length(pg_temp.report('receipts','{"export":true}')->'rows'),81,'Export includes every matching receipt, not the loaded 25');
insert into tap_results select is(pg_temp.report('receipts','{"query":"OLD-RECEIPT"}')->'rows'->0->>'reference','TEST-OLD-RECEIPT','Search finds a receipt from an earlier year without manually loading old pages');
insert into tap_results select is((pg_temp.report('receipts','{"from":"2025-02-02","to":"2025-02-02"}')->>'total')::integer,1,'Receipt dates use the Manila calendar boundary');
insert into tap_results select is((pg_temp.report('credit_invoices','{"status":"outstanding","export":true}')->>'total')::integer,119,'All-date outstanding exports include partial and old unknown-date debt, excluding paid');
insert into tap_results select is((pg_temp.report('credit_invoices','{"status":"paid"}')->'rows'->0->>'balance'),'0','Paid status comes from the payment ledger');
insert into tap_results select is((pg_temp.report('credit_invoices','{"status":"overdue"}')->>'total')::integer,0,'Unknown due dates are not invented overdue dates');
insert into tap_results select is((pg_temp.report('credit_invoices','{"status":"unconfirmed"}')->>'total')::integer,119,'Unconfirmed bucket retains old outstanding invoices');
insert into tap_results select is((pg_temp.report('credit_invoices',jsonb_build_object('entityId',pg_temp.i(200),'export',true))->>'total')::integer,60,'Two clients with the same name remain separated by account ID');
insert into tap_results select is((pg_temp.report('credit_invoices',jsonb_build_object('query','TEST-OLD-INVOICE-2','export',true))->>'complete'),'true','Filtered invoice export is a complete selection');
insert into tap_results select is((pg_temp.report('credit_payments','{"export":true}')->>'total')::integer,2,'Customer payment export reads every matching ledger entry');
insert into tap_results select is((pg_temp.report('supplier_invoices','{"status":"outstanding"}')->'rows'->0->>'balance'),'15000','Supplier export uses the verified outstanding balance after payment');
insert into tap_results select is((public.agri_command('supplier_account_book',pg_temp.ctx()||'{"status":"outstanding"}')->>'matchingTotal')::integer,1,'Daily supplier outstanding view includes partly paid bills');
insert into tap_results select is((pg_temp.report('supplier_payments','{"export":true}')->>'total')::integer,2,'Supplier activity keeps invoice and external payment history');
insert into tap_results select lives_ok($$select pg_temp.report('stock','{"export":true}');select pg_temp.report('purchases','{"export":true}');select pg_temp.report('audit','{"export":true}')$$,'Empty stock/receiving registers and full audit exports are valid');
insert into tap_results select throws_ok($$select pg_temp.report('receipts','{"from":"2026-11-05","to":"2026-11-01"}')$$,'P0001','The ending date must be on or after the starting date','Reversed dates cannot create a misleading export');
insert into tap_results select throws_ok($$select pg_temp.report('receipts','{"offset":25,"export":true}')$$,'P0001','Export the complete selection from its beginning','Export cannot silently start from a later page');
