begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create temporary table tap_results(line text);
create temporary table report_fixture(key text primary key,value jsonb);
grant all on tap_results,report_fixture to authenticated;
create function pg_temp.i(n integer) returns uuid language sql immutable as $$select ('79000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i(1),'session_id',pg_temp.i(1),'role','authenticated')::text,true);
create function pg_temp.ctx() returns jsonb language sql stable as $$select jsonb_build_object('organizationId',b.organization_id,'branchId',b.id) from public.branches b join public.organizations o on o.id=b.organization_id where o.name='TEST record exports' and b.code='B01'$$;
create function pg_temp.report(kind text,extra jsonb default '{}') returns jsonb language sql as $$select public.agri_command('record_report',pg_temp.ctx()||jsonb_build_object('kind',kind)||extra)$$;
set local role authenticated;
select public.agri_command('bootstrap','{"name":"TEST record exports","ownerName":"TEST owner"}');
select public.agri_command('register_device',pg_temp.ctx()||jsonb_build_object('deviceId',pg_temp.i(10),'name','TEST export fixture PC'));
reset role;
select pg_temp.i(100+n),(pg_temp.ctx()->>'organizationId')::uuid,(pg_temp.ctx()->>'branchId')::uuid,pg_temp.i(10),pg_temp.i(1),(select (value->>'shiftId')::uuid from report_fixture where key='shift'),now()-n*interval '1 minute',9900,10000,'TEST-RECEIPT-'||n,jsonb_build_object('total',9900,'items','[]'::jsonb) from generate_series(1,80)n;
values(pg_temp.i(199),(pg_temp.ctx()->>'organizationId')::uuid,(pg_temp.ctx()->>'branchId')::uuid,pg_temp.i(10),pg_temp.i(1),(select (value->>'shiftId')::uuid from report_fixture where key='shift'),'2025-02-01T16:00:00Z',100,100,'TEST-OLD-RECEIPT','{"items":[]}');
select pg_temp.i(300+n),(pg_temp.ctx()->>'organizationId')::uuid,(pg_temp.ctx()->>'branchId')::uuid,pg_temp.i(case when n<=60 then 200 else 201 end),'TEST-OLD-INVOICE-'||n,'{"name":"TEST same customer"}','TEST merchant',12345,'2025-03-01T00:00:00Z','{"items":[]}','opening',repeat('a',64),n+1 from generate_series(1,120)n;
set local role authenticated;
select public.agri_command('collect_credit_payment',pg_temp.ctx()||jsonb_build_object('requestId',pg_temp.i(500),'saleId',pg_temp.i(301),'shiftId',(select value->>'shiftId' from report_fixture where key='shift'),'amount',12345,'reference','TEST paid in full','reason','TEST actual fixture cash'));
select public.agri_command('collect_credit_payment',pg_temp.ctx()||jsonb_build_object('requestId',pg_temp.i(501),'saleId',pg_temp.i(302),'shiftId',(select value->>'shiftId' from report_fixture where key='shift'),'amount',1000,'reference','TEST partial payment','reason','TEST actual fixture cash'));
reset role;
set local role authenticated;
select public.agri_command('supplier_record_invoice',pg_temp.ctx()||jsonb_build_object('requestId',pg_temp.i(601),'supplierId',pg_temp.i(600),'reference','TEST supplier bill','issuedOn',(now() at time zone 'Asia/Manila')::date,'term',30,'expectedDueOn',(now() at time zone 'Asia/Manila')::date+30,'amount',20000,'reason','TEST supplier document','confirmed',true));
select public.agri_command('supplier_record_payment',pg_temp.ctx()||jsonb_build_object('requestId',pg_temp.i(602),'billId',pg_temp.i(601),'expectedVersion',1,'expectedBalance',20000,'amount',5000,'method','bank','paidOn',(now() at time zone 'Asia/Manila')::date,'reference','TEST supplier paid','reason','TEST external payment','confirmed',true));
reset role;
set local role authenticated;
reset role;
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i(2),'session_id',pg_temp.i(2),'role','authenticated')::text,true);
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i(1),'session_id',pg_temp.i(1),'role','authenticated')::text,true);
set local role authenticated;
reset role;
select line from tap_results;
rollback;
